fn solve(a: i8, b: i8, c: i8) -> i8 {
    // Sort the sides so that x <= y <= z
    let mut sides = [a, b, c];
    sides.sort();
    let x = sides[0] as i32;
    let y = sides[1] as i32;
    let z = sides[2] as i32;

    // If the sum of the two smaller sides already exceeds the largest, no operations are needed.
    if x + y > z {
        0
    } else {
        // Otherwise, we need (z - (x + y) + 1) increments on the smaller sides in total.
        (z - (x + y) + 1) as i8
    }
}

